parameters.jsCode:
// Convierte la respuesta de Claude en UNA fila para la pestaña "Perfil".
// La columna "Clave" siempre vale "principal": así cada vez que subes un CV nuevo
// se ACTUALIZA la misma fila en vez de crear otra.
const p = $json.output;
const form = $('Formulario CV').first().json;

return [{
  json: {
    'Clave': 'principal',
    'Actualizado': $now.toFormat('yyyy-LL-dd HH:mm'),
    'Nombre': p.nombre || '',
    'Email': p.email || '',
    'Resumen': p.resumen_profesional || '',
    'Cargos objetivo': (p.cargos_objetivo || []).join(', '),
    // Puedes editar esta columna a mano en la hoja: el Flujo 2 busca con estas palabras.
    'Keywords': (p.keywords_busqueda || []).slice(0, 6).join(', '),
    'Habilidades': (p.habilidades_tecnicas || []).concat(p.habilidades_blandas || []).join(', '),
    'Idiomas': (p.idiomas || []).join(', ') || form['Idiomas y nivel'] || '',
    'Modalidad': form['Modalidad'] || 'Ambos',
    'Salario esperado': form['Salario esperado (USD/mes)'] || '',
    'Perfil JSON': JSON.stringify(p),
  }
}];

// Una fila por cada pregunta que Claude necesita que respondas.
// Tú escribes la respuesta en la columna "Respuesta" de la hoja.
const preguntas = $('Generar perfil (Claude)').first().json.output.preguntas_aclaracion || [];
const hoy = $now.toFormat('yyyy-LL-dd');

return preguntas.map(pregunta => ({
  json: { 'Fecha': hoy, 'Pregunta': pregunta, 'Respuesta': '', 'Origen': 'CV' }
}));
